// Normalize FRESHMAN_COURSES so that:
// 1. physics_2, chemistry_2, and biology_2 chapters merge into Physics, Chemistry, and Biology
// 2. Every course uses ONLY the exact subject name (no course code numbers) across all 20 subjects
const mergedCourseMap = new Map<Subject, FreshmanCourse>();

for (const rawCourse of RAW_FRESHMAN_COURSES) {
  const canonicalSubj: Subject =
    rawCourse.subject === 'physics_2'
      ? 'physics'
      : rawCourse.subject === 'chemistry_2'
      ? 'chemistry'
      : rawCourse.subject === 'biology_2'
      ? 'biology'
      : rawCourse.subject;

  const meta = SUBJECT_NAME_BY_ID[canonicalSubj];
  if (!meta) continue;

  const cleanChapters = rawCourse.chapters.map((ch) => ({
    ...ch,
    subject: canonicalSubj,
    courseCode: meta.name,
    moduleName: meta.name,
  }));

  const existing = mergedCourseMap.get(canonicalSubj);
  if (!existing) {
    mergedCourseMap.set(canonicalSubj, {
      ...rawCourse,
      id: meta.id,
      code: meta.name,
      title: meta.name,
      shortTitle: meta.name,
      subject: canonicalSubj,
      chapters: cleanChapters.map((ch, idx) => ({ ...ch, chapterNumber: idx + 1 })),
    });
  } else {
    const combinedChapters = [...existing.chapters, ...cleanChapters].map((ch, idx) => ({
      ...ch,
      chapterNumber: idx + 1,
    }));
    mergedCourseMap.set(canonicalSubj, {
      ...existing,
      keyTopics: Array.from(new Set([...existing.keyTopics, ...rawCourse.keyTopics])),
      chapters: combinedChapters,
    });
  }
}

export const FRESHMAN_COURSES: FreshmanCourse[] = Array.from(mergedCourseMap.values())
  .map((course) => {
    const extraForSubj = EXTRA_ENLARGED_NOTES[course.subject];
    if (!extraForSubj) return course;
    return {
      ...course,
      chapters: course.chapters.map((ch) => {
        const extraSecs = extraForSubj[ch.chapterNumber];
        if (!extraSecs || extraSecs.length === 0) return ch;
        return {
          ...ch,
          sections: [...ch.sections, ...extraSecs],
        };
      }),
    };
  })
  .sort(
    (a, b) => (SUBJECT_NAME_BY_ID[a.subject]?.order || 99) - (SUBJECT_NAME_BY_ID[b.subject]?.order || 99)
  );

// Convenience flat list of all chapters across all modules
export const ALL_FRESHMAN_CHAPTERS: MasterNoteChapter[] = FRESHMAN_COURSES.flatMap(c => c.chapters);

